  write("o is objectp: %d\n", objectp(o));
  write("o nullp: %d\n", nullp(o));
  write("array[0] objectp: %d\n", objectp(o));
  write("clonep(no object): %d\n", clonep());
  write("clonep(0): %d\n", clonep(0));
  write("clonep(\"str\"): %d\n", clonep("str"));
  write("clonep(f): %d\n", clonep((: 1 :)));
  write("clonep(({}) ): %d\n", clonep(({})));
  object b = load_object("/single/void");
  object c = clone_object("/single/void");
  write("clonep(b)=%d clonep(c)=%d\n", clonep(b), clonep(c));
  object c2 = clone_object("/single/void");
  destruct(c); destruct(c2);
  write("clonep(destructed var)=%d\n", clonep(c));
  write("objectp(destructed var)=%d\n", objectp(c));
  return 0;
